-/// Whether `marker` occurs in `text` outside a double-quoted string. A string
-/// is opened by `"` and closed by an unescaped `"`; a backslash escapes the
-/// character after it inside a string.
-fn has_marker_outside_string(text: &str, marker: &str) -> bool {
-    let mut in_string = false;
+/// Whether `marker` occurs in `text` outside a quoted string. A string is
+/// opened by `"` (and by `'` when `single_quotes` is set) and closed by the
+/// next unescaped quote of the same kind; a backslash escapes the character
+/// after it inside a string.
+fn has_marker_outside_string(text: &str, marker: &str, single_quotes: bool) -> bool {
+    let mut quote = None;
     let mut escaped = false;
     for (index, c) in text.char_indices() {
-        if in_string {
+        if let Some(open) = quote {
             if escaped {
                 escaped = false;
             } else if c == '\\' {
                 escaped = true;
-            } else if c == '"' {
-                in_string = false;
+            } else if c == open {
+                quote = None;
             }
-        } else if c == '"' {
-            in_string = true;
+        } else if c == '"' || (single_quotes && c == '\'') {
+            quote = Some(c);
         } else if text[index..].starts_with(marker) {
             return true;
         }
